  'planner.subtitle': {
    en: 'Plan, log and balance your daily pregnancy meals according to your location and trimester nutrition benchmarks.',
    hi: 'अपने स्थान और तिमाही पोषण मानकों के अनुसार अपने दैनिक गर्भावस्था आहार की योजना बनाएं, दर्ज करें और संतुलित करें।',
    kn: 'ನಿಮ್ಮ ಸ್ಥಳ ಮತ್ತು ತ್ರೈಮಾಸಿಕ ಪೌಷ್ಟಿಕಾಂಶ ಮಾನದಂಡಗಳಿಗೆ ಅನುಗುಣವಾಗಿ ನಿಮ್ಮ ದೈನಂದಿನ ಗರ್ಭಾವಸ್ಥೆಯ ಊಟವನ್ನು ಯೋಜಿಸಿ, ದಾಖಲಿಸಿ ಮತ್ತು ಸಮತೋಲನಗೊಳಿಸಿ.',
    ta: 'உங்கள் இருப்பிடம் மற்றும் முப்பருவ ஊட்டச்சத்து அளவுகோல்களின்படி உங்கள் தினசரி கர்ப்பகால உணவைத் திட்டமிடுங்கள்.',
    te: 'మీ స్థానం మరియు త్రైమాసిక పోషకాహార ప్రమాణాల ప్రకారం మీ రోజువారీ గర్భధారణ భోజనాన్ని ప్లాన్ చేయండి, రికార్డ్ చేయండి మరియు సమతుల్యం చేయండి.',
    ml: 'നിങ്ങളുടെ സ്ഥലവും ത്രൈമാസിക പോഷകാഹാര മാനദണ്ഡങ്ങളും അനുസരിച്ച് ദിവസേനയുള്ള ഭക്ഷണങ്ങൾ ആസൂത്രണം ചെയ്യുക.',
    mr: 'तुमचे स्थान आणि तिमाही पोषण मानकांनुसार तुमच्या दैनंदिन गर्भधारणेच्या आहाराचे नियोजन करा, नोंदवा आणि संतुलित करा.',
    bn: 'আপনার অবস্থান এবং ত্রৈমাসিক পুষ্টির মানদণ্ড অনুযায়ী আপনার দৈনিক গর্ভাবস্থার খাবারের পরিকল্পনা করুন।',
    gu: 'તમારા સ્થાન અને ત્રિમાસિક પોષણના ધોરણો અનુસાર તમારા દૈનિક ગર્ભાવસ્થાના ભોજનનું આયોજન કરો.',
    pa: 'ਆਪਣੇ ਸਥਾਨ ਅਤੇ ਤਿਮਾਹੀ ਪੋਸ਼ਣ ਮਾਪਦੰਡਾਂ ਦੇ ਅਨੁਸਾਰ ਆਪਣੇ ਰੋਜ਼ਾਨਾ ਗਰਭ ਅਵਸਥਾ ਦੇ ਭੋਜਨ ਦੀ ਯੋਜਨਾ ਬਣਾਓ।',
    or: 'ଆପଣଙ୍କର ସ୍ଥାନ ଏବଂ ତ୍ରୈମାସିକ ପୋଷଣ ମାନଦଣ୍ଡ ଅନୁଯାୟୀ ଆପଣଙ୍କର ଦୈନିକ ଗର୍ଭାବସ୍ଥା ଖାଦ୍ୟ ଯୋଜନା କରନ୍ତୁ।',
    ur: 'اپنے مقام اور سہ ماہی کے غذائی معیارات کے مطابق روزانہ کے کھانے کی منصوبہ بندی کریں۔',
    as: 'আপোনাৰ স্থান আৰু ত্ৰৈমাসিক পুষ্টিৰ মানদণ্ড অনুসৰি আপোনাৰ দৈনিক গৰ্ভাৱস্থাৰ আহাৰ পৰিকল্পনা কৰক।'
  },
