  'scanner.snapMeal': {
    en: 'Snap your meal and track your nutrition automatically. Review detected foods, confirm portions, and compute all 13 vitamins & 11 minerals.',
    kn: 'ನಿಮ್ಮ ಊಟದ ಚಿತ್ರ ತೆಗೆದು ಪೌಷ್ಟಿಕಾಂಶವನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಲೆಕ್ಕಹಾಕಿ. ಗುರುತಿಸಲಾದ ಆಹಾರವನ್ನು ಪರಿಶೀಲಿಸಿ, ಪ್ರಮಾಣ ದೃಢೀಕರಿಸಿ ಮತ್ತು ಎಲ್ಲಾ ವಿಟಮಿನ್ ಹಾಗೂ ಖನಿಜಗಳನ್ನು ತಿಳಿಯಿರಿ.',
    hi: 'अपने भोजन की तस्वीर लें और पोषण ट्रैक करें। पहचाने गए खाद्य पदार्थों की समीक्षा करें, मात्रा की पुष्टि करें और सभी 13 विटामिन एवं 11 खनिजों की गणना करें।',
    ta: 'உங்கள் உணவை படம் எடுத்து ஊட்டச்சத்தை தானாக கண்காணிக்கவும். கண்டறியப்பட்ட உணவுகளை சரிபார்த்து, அனைத்து வைட்டமின்களையும் தாதுக்களையும் கணக்கிடுங்கள்.',
    te: 'మీ భోజనాన్ని స్నాప్ చేయండి మరియు పోషకాలను స్వయంచాలకంగా ట్రాక్ చేయండి. గుర్తించిన ఆహారాలను సమీక్షించండి మరియు అన్ని విటమిన్లు మరియు ఖనిజాలను లెక్కించండి.',
    ml: 'നിങ്ങളുടെ ഭക്ഷണം ഫോട്ടോ എടുത്ത് പോഷകങ്ങൾ സ്വയമേവ ട്രാക്ക് ചെയ്യുക. വിറ്റാമിനുകളും ധാതുക്കളും പൂർണ്ണമായി പരിശോധിക്കുക.'
  },
