    ta: 'கடுமையான தலைவலி, பார்வை மங்குதல், திடீர் வீக்கம், ரத்தப்போக்கு அல்லது குழந்தையின் அசைவு குறைதல் உடனடியாக மருத்துவரை அணுகவும்.',
    te: 'తీవ్రమైన తలనొప్పి, చూపు మసకబారడం, అకస్మాత్తుగా వాపు, రక్తస్రావం లేదా పిండం కదలికలు తగ్గితే వెంటనే వైద్యుడిని సంప్రదించండి.',
    ml: 'കഠിനമായ തലവേദന, കാഴ്ച മങ്ങൽ, പെട്ടെന്നുള്ള നീർക്കെട്ട്, രക്തസ്രാവം, കുഞ്ഞിന്റെ അനക്കം കുറയൽ എന്നിവ ഉണ്ടായാൽ ഉടൻ ചികിത്സ തേടുക.'
