  'profile.locationDesc': {
    en: 'Select your Village or Taluk once. The app automatically determines your Taluk, District, State, and broader region for local foods, recipes, and healthcare schemes.',
    kn: 'ನಿಮ್ಮ ಹಳ್ಳಿ ಅಥವಾ ತಾಲೂಕನ್ನು ಒಮ್ಮೆ ಆಯ್ಕೆಮಾಡಿ. ಅಪ್ಲಿಕೇಶನ್ ಸ್ಥಳೀಯ ಆಹಾರ, ಪಾಕವಿಧಾನಗಳು ಮತ್ತು ಆರೋಗ್ಯ ಯೋಜನೆಗಳಿಗಾಗಿ ನಿಮ್ಮ ಜಿಲ್ಲೆ ಮತ್ತು ರಾಜ್ಯವನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ನಿರ್ಧರಿಸುತ್ತದೆ.',
    hi: 'एक बार अपना गांव या तालुक चुनें। ऐप स्थानीय खाद्य पदार्थों, व्यंजनों और स्वास्थ्य योजनाओं के लिए आपके जिले और राज्य का स्वतः निर्धारण करता है।',
    ta: 'உங்கள் கிராமம் அல்லது தாலுகாவை ஒருமுறை தேர்ந்தெடுக்கவும். உள்ளூர் உணவுகள் மற்றும் சுகாதார திட்டங்களுக்காக உங்கள் மாவட்டம் மற்றும் மாநிலத்தை செயலி தானாகவே தீர்மானிக்கிறது.',
    te: 'మీ గ్రామం లేదా తాలూకాను ఒకసారి ఎంచుకోండి. స్థానిక ఆహారాలు మరియు ఆరోగ్య పథకాల కోసం యాప్ మీ జిల్లా మరియు రాష్ట్రాన్ని స్వయంచాలకంగా నిర్ణయిస్తుంది.',
    ml: 'നിങ്ങളുടെ ഗ്രാമമോ താലൂക്കോ ഒരിക്കൽ തിരഞ്ഞെടുക്കുക. പ്രാദേശിക ഭക്ഷണങ്ങൾക്കും ആരോഗ്യ പദ്ധതികൾക്കുമായി ആപ്പ് നിങ്ങളുടെ ജില്ലയും സംസ്ഥാനവും സ്വയമേവ നിർണ്ണയിക്കുന്നു.'
  },
